use crate::{bq060 as b,catalog,model::*,rules::*,unit_support::*,abi112_review_play_tests::Trace};
fn setup()->(Game,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));fund(&mut g,0,"BQ064",1);let id=held(&mut g,b::ID,0);(g,id)}
fn play(id:&str,mode:&str)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),option:Some(mode.into()),region:if mode=="generate"{Some(0)}else{None},..Action::new("play")}}
fn top(g:&mut Game){for _ in 0..16{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!();}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq060_original_modes_and_closed_registry(){let c=catalog::card(b::ID);assert_eq!((c.cost,c.color.as_str(),c.supported),(1,"灰",false));assert_eq!(c.subtypes,["命令","精神"]);assert_eq!(c.loyalty,["灰色"]);let d=b::definition();assert!(matches!(d.abilities[0].timing,Timing::Fast));assert_eq!(d.abilities[0].modes.len(),3);for n in 0..3{let mut x=d.clone();x.abilities[0].modes[n].ops.clear();assert!(b::validate_definition(b::ID,&x).is_err());}assert!(b::validate_definition("JC001",&d).is_err());}
#[test]fn bq060_shoggoth_payment_and_exact_mode_payload(){let(mut g,id)=setup();g.players[0].society_zone.card=None;reject(&mut g,0,play(&id,"generate"));g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let mut a=play(&id,"shield");a.target_id=Some("society:p0".into());reject(&mut g,0,a);reject(&mut g,0,play(&id,"all"));g.players[0].assets.clear();reject(&mut g,0,play(&id,"generate"));fund(&mut g,0,"JC002",1);reject(&mut g,0,play(&id,"generate"));}
#[test]fn bq060_shield_current_live_owned_core_not_parked_hidden_or_enemy(){for mode in 0..4{let(mut g,id)=setup();let c=g.make_card("BQ046",0);let cid=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:if mode==1{Some(c.clone())}else{None}});if mode!=1{g.regions[0].cards.push(c);}if mode==2{g.board_mut(&cid).unwrap().face_down=true;}if mode==3{g.board_mut(&cid).unwrap().controller=1;}act(&mut g,0,play(&id,"shield"));top(&mut g);assert_eq!(g.resources(0),0);if mode==1{assert_eq!(g.core_zones[0].card.as_ref().unwrap().shield,0);}else{assert_eq!(g.board(&cid).unwrap().1.shield,u32::from(mode==0));}restore(&mut g);}}
#[test]fn bq060_generated_identity_leaves_vanish_and_target_instance_rechecked(){for replaced in [false,true]{let(mut g,id)=setup();act(&mut g,0,play(&id,"generate"));if replaced{g.regions[0].card=g.make_card("DQJC115",0);}top(&mut g);let tokens=g.regions[0].cards.iter().filter(|c|c.definition=="TK010").cloned().collect::<Vec<_>>();assert_eq!(tokens.len(),usize::from(!replaced));if let Some(t)=tokens.first(){assert!(t.generated.is_some());assert_eq!(t.controller,0);g.remove_dead(&t.id,RemovalCause::Destroy);g.drive().unwrap();assert!(!g.batch3_physical_cards().any(|c|c.definition=="TK010"));}restore(&mut g);}}
#[test]fn bq060_restore_rejects_missing_foreign_or_duplicate_frames(){let(mut g,id)=setup();act(&mut g,0,play(&id,"generate"));for n in 0..6{let mut x=g.clone();let i=x.stack.last_mut().unwrap();if n==0{i.frame=None;}else{let f=i.frame.as_mut().unwrap();match n{1=>f.source.card.definition="JC001".into(),2=>f.steps.clear(),3=>f.already_paid.clear(),4=>f.targets.clear(),_=>f.steps[0].context=1}}bad(&g,&x);}let mut x=g.clone();x.effects.push_back(Effect::Frame{frame:Box::new(x.stack.last().unwrap().frame.as_ref().unwrap().clone())});bad(&g,&x);restore(&mut g);}
fn choice(t:&mut Trace,p:&Pending){if matches!(p.choice.kind.as_str(),"investigation"|"order"){t.action(p.seat,Action{choice_id:Some(p.choice.id.clone()),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});}else{let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();t.choose(ids);}}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn prepared(mode:&str,index:usize)->serde_json::Value{let(mut g,id)=setup();if mode=="shield"{let c=g.make_card("BQ046",0);g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:None});g.regions[0].cards.push(c);}for s in 0..4{held(&mut g,"JC125",s);}let mut t=Trace::new_preserving_rng(g,format!("bq060-prepared-{mode}"),index);t.action(0,play(&id,mode));for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){choice(&mut t,&p);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty()&&t.room.game.mystic_contest.is_none(){break;}else{t.pass();}}let g=&t.room.game;assert!(g.pending.is_none()&&g.mystic_contest.is_none());match mode{"shield"=>assert_eq!(g.regions[0].cards.iter().find(|c|c.definition=="BQ046").unwrap().shield,1),"generate"=>assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK010").count(),1),_=>assert_eq!(g.mystic_history.len(),1)}if mode=="contest"{for n in 0..2{let mut x=g.clone();if n==0{x.mystic_history[0].actor_bonus=1;}else{x.mystic_history[0].ability_key="bq060-other".into();}bad(g,&x);}}duplicate(t.value())}
fn natural()->serde_json::Value{use crate::deck;fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="bq060-natural".into();d.society_id=Some("MSBQ02".into());d.core_card_id=Some("BQ046".into());d.cards=[(b::ID,3),("BQ064",3),("BQ048",3),("BQ050",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID,"BQ046","BQ048","BQ050"].contains(&c.id.as_str()){c.supported=true;}}let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq060".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
 let(seed,g)=(1..2049).find_map(|seed|{let g=construct(seed);[b::ID,"BQ064"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id)).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"bq060-natural-fifty-plus-core-generated-tentacle".into(),780);let mut done=false;for _ in 0..600{if let Some(p)=t.room.game.pending.clone(){choice(&mut t,&p);continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.is_empty(){legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ064")))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.option.as_deref()==Some("generate"))};if let Some(a)=a{if a.action.kind=="play"{done=true;}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(done);assert_eq!(t.room.game.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition=="TK010"&&c.controller==0).count(),1);let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"separateCore":1,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn bq060_native_three_modes_and_natural_export(){let cases=vec![natural(),prepared("shield",781),prepared("contest",782),prepared("generate",783)];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq060.rs",include_bytes!("bq060.rs").as_slice()),("rust-game/src/bq060_tests.rs",include_bytes!("bq060_tests.rs").as_slice()),("rust-game/src/core_zone.rs",include_bytes!("core_zone.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("BQ060_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn bq060_contest_pending_corruption_rejected(){let(mut g,id)=setup();for s in 0..4{held(&mut g,"JC125",s);}act(&mut g,0,play(&id,"contest"));top(&mut g);assert!(g.mystic_contest.is_some());restore(&mut g);for n in 0..3{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.seat=(p.seat+1)%4,1=>p.choice.options.clear(),_=>if let ChoiceResolution::Frame{frame,..}=&mut p.resolution{frame.steps.clear();}}bad(&g,&x);}}
